"""Every figure in results/figures/, generated by script (never by hand).

Design rules applied throughout:
- One y-axis per panel. Two measures of different scale get two panels, never a
  second axis.
- Categorical colour is assigned by entity in a fixed order (Round 0 = blue,
  Round 1 = orange) and is never cycled or reassigned by rank.
- The solved heatmap uses a single-hue sequential ramp, light -> dark.
- A legend is present whenever two series are drawn; values are direct-labelled
  rather than left to the grid, which also satisfies the relief rule for the
  lower-contrast palette slot.
- Grid and axes are recessive; marks are thin.
"""

from __future__ import annotations

import json
import os
from typing import Any

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd
from matplotlib.colors import LinearSegmentedColormap
from matplotlib.patches import Patch

from analysis.summarise import SUMMARY_PATH, load_episodes
from harness.trajectory import iter_trajectories

FIG_DIR = os.path.join("results", "figures")

# Categorical slots, fixed order. Round 0 = slot 1, Round 1 = slot 2.
ROUND_COLOUR = {0: "#2a78d6", 1: "#eb6834"}
SLOT3 = "#1baf7a"

SURFACE = "#fcfcfb"
TEXT_PRIMARY = "#0b0b0b"
TEXT_SECONDARY = "#52514e"
GRID = "#e4e3df"

# Single-hue sequential ramp (blue 100 -> 700) for magnitude encoding.
SEQUENTIAL = LinearSegmentedColormap.from_list(
    "seq_blue",
    ["#f3f7fd", "#cde2fb", "#9ec5f4", "#6da7ec", "#3987e5", "#256abf", "#0d366b"],
)


def _style(axes: plt.Axes, *, grid_axis: str = "y") -> None:
    axes.set_facecolor(SURFACE)
    for side in ("top", "right"):
        axes.spines[side].set_visible(False)
    for side in ("left", "bottom"):
        axes.spines[side].set_color(GRID)
    axes.tick_params(colors=TEXT_SECONDARY, labelsize=8, length=3)
    if grid_axis in ("x", "y", "both"):
        axes.grid(axis=grid_axis, color=GRID, linewidth=0.8, zorder=0)
    axes.set_axisbelow(True)


def _figure(width: float, height: float) -> tuple[plt.Figure, plt.Axes]:
    figure, axes = plt.subplots(figsize=(width, height), facecolor=SURFACE)
    _style(axes)
    return figure, axes


def _save(figure: plt.Figure, name: str) -> str:
    os.makedirs(FIG_DIR, exist_ok=True)
    path = os.path.join(FIG_DIR, name)
    figure.savefig(path, dpi=160, bbox_inches="tight", facecolor=SURFACE)
    plt.close(figure)
    return path


def _rounds(frame: pd.DataFrame) -> list[int]:
    return sorted(int(r) for r in frame["round"].unique())


def _ordered_games(frame: pd.DataFrame) -> list[tuple[str, str, str]]:
    """(game_id, short_id, split) with dev first, then test, alphabetical."""
    seen: dict[str, tuple[str, str, str]] = {}
    for _, row in frame.iterrows():
        seen[row["game"]] = (row["game"], row["short_id"], row["split"])
    return sorted(seen.values(), key=lambda e: (e[2] != "dev", e[1]))


# ---------------------------------------------------------------------------
# 1. Solve rate per game, Round 0 vs Round 1, dev/test shaded
# ---------------------------------------------------------------------------


def figure_solve_rate_per_game(frame: pd.DataFrame) -> str:
    games = _ordered_games(frame)
    rounds = _rounds(frame)
    labels = [short for _gid, short, _split in games]
    positions = np.arange(len(games), dtype=float)
    width = 0.8 / max(len(rounds), 1)

    figure, axes = _figure(max(8.0, len(games) * 0.46), 4.2)

    # Shade the test-split region so the real result is visually separated.
    n_dev = sum(1 for _g, _s, split in games if split == "dev")
    if 0 < n_dev < len(games):
        axes.axvspan(
            n_dev - 0.5, len(games) - 0.5, color="#f0efec", zorder=0, linewidth=0
        )
        axes.text(
            (n_dev + len(games) - 1) / 2,
            1.06,
            "test split",
            ha="center",
            fontsize=8,
            color=TEXT_SECONDARY,
        )
        axes.text(
            (n_dev - 1) / 2, 1.06, "dev split", ha="center", fontsize=8,
            color=TEXT_SECONDARY,
        )

    for index, round_index in enumerate(rounds):
        rates = []
        for game_id, _short, _split in games:
            sub = frame[(frame["game"] == game_id) & (frame["round"] == round_index)]
            rates.append(float(sub["solved"].mean()) if len(sub) else np.nan)
        offset = (index - (len(rounds) - 1) / 2) * width
        bars = axes.bar(
            positions + offset,
            rates,
            width=width * 0.92,
            color=ROUND_COLOUR.get(round_index, SLOT3),
            label=f"Round {round_index}",
            zorder=3,
        )
        # Direct-label only the non-zero bars: a number on every bar is noise.
        for bar, rate in zip(bars, rates):
            if rate and not np.isnan(rate) and rate > 0:
                axes.text(
                    bar.get_x() + bar.get_width() / 2,
                    rate + 0.02,
                    f"{rate:.0%}",
                    ha="center",
                    fontsize=7,
                    color=TEXT_SECONDARY,
                )

    axes.set_xticks(positions)
    axes.set_xticklabels(labels, rotation=90, fontsize=8)
    axes.set_ylim(0, 1.12)
    axes.set_yticks([0, 0.25, 0.5, 0.75, 1.0])
    axes.set_yticklabels(["0%", "25%", "50%", "75%", "100%"])
    axes.set_ylabel("Level 1 solve rate across seeds", fontsize=9, color=TEXT_PRIMARY)
    axes.set_title(
        "Level 1 solve rate per game", fontsize=11, color=TEXT_PRIMARY, loc="left"
    )
    if len(rounds) >= 2:
        axes.legend(frameon=False, fontsize=8, loc="upper right")
    return _save(figure, "solve_rate_per_game.png")


# ---------------------------------------------------------------------------
# 2. Actions to solve vs human baseline
# ---------------------------------------------------------------------------


def figure_actions_vs_baseline(frame: pd.DataFrame) -> str:
    solved = frame[(frame["solved"] == 1) & frame["human_baseline_actions"].notna()]
    figure, axes = _figure(6.4, 5.2)

    if solved.empty:
        axes.text(
            0.5,
            0.5,
            "No episodes solved Level 1, so there is no\nactions-to-solve "
            "comparison to draw.",
            ha="center",
            va="center",
            fontsize=10,
            color=TEXT_SECONDARY,
            transform=axes.transAxes,
        )
        axes.set_xticks([])
        axes.set_yticks([])
        axes.set_title(
            "Actions to solve vs human baseline",
            fontsize=11,
            color=TEXT_PRIMARY,
            loc="left",
        )
        return _save(figure, "actions_vs_baseline.png")

    limit = max(
        float(solved["human_baseline_actions"].max()),
        float(solved["actions_used"].max()),
    ) * 1.15
    axes.plot(
        [0, limit], [0, limit], color=GRID, linewidth=1.5, zorder=1,
        label="parity with human",
    )
    for round_index in _rounds(solved):
        sub = solved[solved["round"] == round_index]
        axes.scatter(
            sub["human_baseline_actions"],
            sub["actions_used"],
            s=46,
            color=ROUND_COLOUR.get(round_index, SLOT3),
            edgecolor=SURFACE,
            linewidth=1.5,
            zorder=3,
            label=f"Round {round_index}",
        )
        for _, row in sub.iterrows():
            axes.annotate(
                row["short_id"],
                (row["human_baseline_actions"], row["actions_used"]),
                textcoords="offset points",
                xytext=(6, 3),
                fontsize=7,
                color=TEXT_SECONDARY,
            )

    axes.set_xlim(0, limit)
    axes.set_ylim(0, limit)
    axes.set_xlabel("Human baseline actions for Level 1", fontsize=9, color=TEXT_PRIMARY)
    axes.set_ylabel("Agent actions used", fontsize=9, color=TEXT_PRIMARY)
    axes.set_title(
        "Actions to solve vs human baseline (solved episodes only)",
        fontsize=11,
        color=TEXT_PRIMARY,
        loc="left",
    )
    axes.legend(frameon=False, fontsize=8, loc="upper left")
    axes.grid(color=GRID, linewidth=0.8)
    return _save(figure, "actions_vs_baseline.png")


# ---------------------------------------------------------------------------
# 3. game x seed solved heatmap, one panel per round
# ---------------------------------------------------------------------------


def figure_solved_heatmap(frame: pd.DataFrame) -> str:
    games = _ordered_games(frame)
    rounds = _rounds(frame)
    seeds = sorted(int(s) for s in frame["seed"].unique())

    figure, axes_list = plt.subplots(
        1,
        len(rounds),
        figsize=(3.0 + 1.9 * len(rounds), max(5.0, len(games) * 0.3)),
        facecolor=SURFACE,
        squeeze=False,
    )
    for column, round_index in enumerate(rounds):
        axes = axes_list[0][column]
        matrix = np.full((len(games), len(seeds)), np.nan)
        for row_index, (game_id, _short, _split) in enumerate(games):
            for col_index, seed in enumerate(seeds):
                sub = frame[
                    (frame["game"] == game_id)
                    & (frame["round"] == round_index)
                    & (frame["seed"] == seed)
                ]
                if len(sub):
                    matrix[row_index, col_index] = float(sub["solved"].iloc[0])
        axes.imshow(
            matrix, cmap=SEQUENTIAL, vmin=0, vmax=1, aspect="auto",
            interpolation="nearest",
        )
        axes.set_xticks(range(len(seeds)))
        axes.set_xticklabels([f"seed {s}" for s in seeds], fontsize=8, rotation=45)
        if column == 0:
            axes.set_yticks(range(len(games)))
            axes.set_yticklabels(
                [
                    f"{short}  ({'dev' if split == 'dev' else 'test'})"
                    for _gid, short, split in games
                ],
                fontsize=7,
            )
        else:
            axes.set_yticks([])
        axes.set_title(f"Round {round_index}", fontsize=10, color=TEXT_PRIMARY)
        axes.tick_params(colors=TEXT_SECONDARY, length=0)
        for spine in axes.spines.values():
            spine.set_visible(False)
        # Direct marks, because a two-value heatmap read by colour alone is
        # exactly the colour-only encoding the accessibility pass forbids.
        for row_index in range(len(games)):
            for col_index in range(len(seeds)):
                value = matrix[row_index, col_index]
                if np.isnan(value):
                    mark, colour = "-", TEXT_SECONDARY
                elif value >= 0.5:
                    mark, colour = "solved", SURFACE
                else:
                    mark, colour = "", TEXT_SECONDARY
                if mark:
                    axes.text(
                        col_index, row_index, mark, ha="center", va="center",
                        fontsize=6, color=colour,
                    )

    figure.suptitle(
        "Level 1 solved, per game x seed (filled = solved)",
        fontsize=11,
        color=TEXT_PRIMARY,
        x=0.02,
        ha="left",
    )
    return _save(figure, "solved_heatmap.png")


# ---------------------------------------------------------------------------
# 4. Tokens and wall time per game (two panels, one axis each)
# ---------------------------------------------------------------------------


def figure_tokens_and_time(frame: pd.DataFrame) -> str:
    games = _ordered_games(frame)
    rounds = _rounds(frame)
    labels = [short for _gid, short, _split in games]
    positions = np.arange(len(games), dtype=float)
    width = 0.8 / max(len(rounds), 1)

    figure, axes_list = plt.subplots(
        2,
        1,
        figsize=(max(8.0, len(games) * 0.46), 6.6),
        facecolor=SURFACE,
        sharex=True,
    )
    for axes in axes_list:
        _style(axes)

    for index, round_index in enumerate(rounds):
        offset = (index - (len(rounds) - 1) / 2) * width
        tokens, times = [], []
        for game_id, _short, _split in games:
            sub = frame[(frame["game"] == game_id) & (frame["round"] == round_index)]
            tokens.append(
                float(sub["tokens_total"].mean()) / 1000 if len(sub) else np.nan
            )
            times.append(float(sub["wall_time_s"].mean()) / 60 if len(sub) else np.nan)
        colour = ROUND_COLOUR.get(round_index, SLOT3)
        axes_list[0].bar(
            positions + offset, tokens, width=width * 0.92, color=colour,
            label=f"Round {round_index}", zorder=3,
        )
        axes_list[1].bar(
            positions + offset, times, width=width * 0.92, color=colour,
            label=f"Round {round_index}", zorder=3,
        )

    axes_list[0].set_ylabel("Mean tokens per episode (thousands)", fontsize=9,
                            color=TEXT_PRIMARY)
    axes_list[0].set_title(
        "Cost per game: tokens and wall time (mean across seeds)",
        fontsize=11, color=TEXT_PRIMARY, loc="left",
    )
    axes_list[1].set_ylabel("Mean wall time per episode (minutes)", fontsize=9,
                            color=TEXT_PRIMARY)
    axes_list[1].set_xticks(positions)
    axes_list[1].set_xticklabels(labels, rotation=90, fontsize=8)
    if len(rounds) >= 2:
        axes_list[0].legend(frameon=False, fontsize=8)
    return _save(figure, "tokens_and_time.png")


# ---------------------------------------------------------------------------
# 5. Skill usage frequency and per-skill validation precision
# ---------------------------------------------------------------------------


def figure_skills(frame: pd.DataFrame, index_path: str = "skills/index.json") -> str:
    if not os.path.exists(index_path):
        figure, axes = _figure(7.0, 3.0)
        axes.text(
            0.5, 0.5, "No skill library yet (skills/index.json missing).",
            ha="center", va="center", fontsize=10, color=TEXT_SECONDARY,
            transform=axes.transAxes,
        )
        axes.set_xticks([])
        axes.set_yticks([])
        return _save(figure, "skills.png")

    with open(index_path, encoding="utf-8") as handle:
        index = json.load(handle)
    skills = index.get("skills", [])

    # Usage comes from Round 1 episode records.
    usage: dict[str, int] = {}
    if os.path.exists("results/episodes.jsonl"):
        with open("results/episodes.jsonl", encoding="utf-8") as handle:
            for line in handle:
                line = line.strip()
                if not line:
                    continue
                row = json.loads(line)
                if int(row.get("round", -1)) != 1:
                    continue
                for name, count in (row.get("skill_calls_by_name") or {}).items():
                    usage[name] = usage.get(name, 0) + int(count)

    names = [s["name"] for s in skills]
    precisions = [float(s.get("precision") or 0.0) for s in skills]
    counts = [usage.get(name, 0) for name in names]
    order = np.argsort([-c for c in counts])
    names = [names[i] for i in order]
    precisions = [precisions[i] for i in order]
    counts = [counts[i] for i in order]

    figure, axes_list = plt.subplots(
        1, 2, figsize=(11.0, max(3.2, len(names) * 0.34)), facecolor=SURFACE
    )
    for axes in axes_list:
        _style(axes, grid_axis="x")

    y = np.arange(len(names), dtype=float)
    axes_list[0].barh(y, counts, color=ROUND_COLOUR[1], height=0.68, zorder=3)
    axes_list[0].set_yticks(y)
    axes_list[0].set_yticklabels(names, fontsize=7)
    axes_list[0].invert_yaxis()
    axes_list[0].set_xlabel("Times called in Round 1", fontsize=9, color=TEXT_PRIMARY)
    axes_list[0].set_title("Skill usage frequency", fontsize=10,
                           color=TEXT_PRIMARY, loc="left")
    if counts and max(counts) == 0:
        axes_list[0].text(
            0.5, 0.5, "no skill calls recorded", ha="center", va="center",
            fontsize=9, color=TEXT_SECONDARY, transform=axes_list[0].transAxes,
        )

    axes_list[1].barh(y, precisions, color=ROUND_COLOUR[0], height=0.68, zorder=3)
    axes_list[1].set_yticks(y)
    axes_list[1].set_yticklabels([])
    axes_list[1].set_xlim(0, 1.05)
    axes_list[1].invert_yaxis()
    axes_list[1].set_xlabel("Validation precision on logged data", fontsize=9,
                            color=TEXT_PRIMARY)
    axes_list[1].set_title("Per-skill validation precision", fontsize=10,
                           color=TEXT_PRIMARY, loc="left")
    for index_, value in enumerate(precisions):
        axes_list[1].text(
            value + 0.015, index_, f"{value:.2f}", va="center", fontsize=7,
            color=TEXT_SECONDARY,
        )
    return _save(figure, "skills.png")


# ---------------------------------------------------------------------------
# 6. Example action tapes
# ---------------------------------------------------------------------------

ACTION_ORDER = [
    "RESET", "ACTION1", "ACTION2", "ACTION3", "ACTION4",
    "ACTION5", "ACTION6", "ACTION7", "CALL",
]


def figure_action_tapes(frame: pd.DataFrame, max_examples: int = 3) -> str:
    """Step vs action for a few episodes, with level completion marked."""
    episodes = iter_trajectories(0) + iter_trajectories(1)
    if not episodes:
        figure, axes = _figure(7.0, 3.0)
        axes.text(
            0.5, 0.5, "No trajectories found.", ha="center", va="center",
            fontsize=10, color=TEXT_SECONDARY, transform=axes.transAxes,
        )
        axes.set_xticks([])
        axes.set_yticks([])
        return _save(figure, "action_tapes.png")

    # Prefer episodes that actually completed a level; they are the
    # informative tapes. Fall back to the longest ones.
    def solved_in(records: list[dict[str, Any]]) -> bool:
        return any(int(r.get("levels_completed") or 0) >= 1 for r in records)

    chosen = [e for e in episodes if solved_in(e[2])][:max_examples]
    if len(chosen) < max_examples:
        rest = sorted(
            (e for e in episodes if e not in chosen),
            key=lambda e: -len(e[2]),
        )
        chosen += rest[: max_examples - len(chosen)]
    chosen = chosen[:max_examples]

    figure, axes_list = plt.subplots(
        len(chosen), 1, figsize=(9.0, 2.0 * len(chosen)), facecolor=SURFACE,
        squeeze=False,
    )
    for row, (game_id, seed, records) in enumerate(chosen):
        axes = axes_list[row][0]
        _style(axes, grid_axis="both")
        round_index = int(records[0].get("round", 0)) if records else 0
        steps = [int(r["step"]) for r in records]
        ys = [
            ACTION_ORDER.index(r["action"]) if r["action"] in ACTION_ORDER else len(ACTION_ORDER)
            for r in records
        ]
        axes.scatter(
            steps, ys, s=14, color=ROUND_COLOUR.get(round_index, SLOT3),
            zorder=3, linewidth=0,
        )
        # Mark the step where a level completed.
        previous = 0
        for record in records:
            current = int(record.get("levels_completed") or 0)
            if current > previous:
                axes.axvline(
                    int(record["step"]), color=SLOT3, linewidth=2, zorder=2,
                )
                axes.text(
                    int(record["step"]), len(ACTION_ORDER) - 0.4, " level complete",
                    fontsize=7, color=TEXT_SECONDARY, va="top",
                )
            previous = current
        for record in records:
            if record.get("state") == "GAME_OVER":
                axes.axvline(
                    int(record["step"]), color="#e34948", linewidth=0.8,
                    alpha=0.5, zorder=1,
                )

        axes.set_yticks(range(len(ACTION_ORDER)))
        axes.set_yticklabels(
            [a.replace("ACTION", "A") for a in ACTION_ORDER], fontsize=7
        )
        axes.set_ylim(-0.6, len(ACTION_ORDER) - 0.4)
        axes.set_title(
            f"{game_id.split('-')[0]} seed {seed}, Round {round_index} "
            f"({len(records)} steps)  |  thin red line = GAME_OVER",
            fontsize=9, color=TEXT_PRIMARY, loc="left",
        )
        if row == len(chosen) - 1:
            axes.set_xlabel("Step", fontsize=9, color=TEXT_PRIMARY)
    figure.tight_layout()
    return _save(figure, "action_tapes.png")


# ---------------------------------------------------------------------------


def build_all_figures(episodes_path: str | None = None) -> list[str]:
    frame = load_episodes(episodes_path) if episodes_path else load_episodes()
    paths = [
        figure_solve_rate_per_game(frame),
        figure_actions_vs_baseline(frame),
        figure_solved_heatmap(frame),
        figure_tokens_and_time(frame),
        figure_skills(frame),
        figure_action_tapes(frame),
    ]
    return paths
